#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 10
static int parent[MAXN];
static int rank_arr[MAXN];

static int find_set(int x) {
    if (parent[x] != x) {
        parent[x] = find_set(parent[x]);
    }
    return parent[x];
}

static void union_set(int a, int b) {
    int ra = find_set(a);
    int rb = find_set(b);
    if (ra == rb) return;
    if (rank_arr[ra] < rank_arr[rb]) {
        parent[ra] = rb;
    } else if (rank_arr[ra] > rank_arr[rb]) {
        parent[rb] = ra;
    } else {
        parent[rb] = ra;
        rank_arr[ra]++;
    }
}

int main(int argc, char *argv[]) {
    // initialise union‑find for elements 0..9
    for (int i = 0; i < MAXN; ++i) {
        parent[i] = i;
        rank_arr[i] = 0;
    }

    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    int i = 1; // start after program name
    while (i < argc) {
        char *cmd = argv[i];
        if (strcmp(cmd, "U") == 0) {               // UNION a b
            if (i + 2 >= argc) { puts("INVALID"); break; }
            long a = strtol(argv[i+1], NULL, 10);
            long b = strtol(argv[i+2], NULL, 10);
            if (a < 0 || a >= MAXN || b < 0 || b >= MAXN) {
                puts("INVALID");
            } else {
                union_set((int)a, (int)b);
                printf("UNION %ld %ld\n", a, b);
            }
            i += 3;
        } else if (strcmp(cmd, "F") == 0) {        // FIND a
            if (i + 1 >= argc) { puts("INVALID"); break; }
            long a = strtol(argv[i+1], NULL, 10);
            if (a < 0 || a >= MAXN) {
                puts("INVALID");
            } else {
                int root = find_set((int)a);
                printf("FIND %ld=%d\n", a, root);
            }
            i += 2;
        } else if (strcmp(cmd, "C") == 0) {        // CONNECTED a b
            if (i + 2 >= argc) { puts("INVALID"); break; }
            long a = strtol(argv[i+1], NULL, 10);
            long b = strtol(argv[i+2], NULL, 10);
            if (a < 0 || a >= MAXN || b < 0 || b >= MAXN) {
                puts("INVALID");
            } else {
                printf("%s\n", find_set((int)a) == find_set((int)b) ? "YES" : "NO");
            }
            i += 3;
        } else {
            puts("NOOP");
            return 0;
        }
    }
    return 0;
}
